#!/usr/bin/env node
/**
 * Generates the token artifacts of @zhin.js/console-ui from tokens/tokens.mjs (ADR 0063 D17).
 *
 *   node tokens/generate.mjs          write client/styles/generated/*
 *   node tokens/generate.mjs --check  fail when a generated file is out of date (CI, tests)
 *
 * Generated files carry a "do not edit" header; edit tokens/tokens.mjs or tokens/colors.css.
 */
import { mkdirSync, readFileSync, writeFileSync } from 'node:fs';
import { dirname, join, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';
import {
  PREFIX,
  baseTierVariables,
  buildScale,
  containerRanges,
  customMedia,
  resolveSemanticValue,
  sizingValues,
  tokens,
} from './scale.mjs';

const here = dirname(fileURLToPath(import.meta.url));
const packageRoot = resolve(here, '..');
export const GENERATED_DIR = join(packageRoot, 'client/styles/generated');

const HEADER = (what) => `/*
 * GENERATED by @zhin.js/console-ui tokens/generate.mjs from tokens/tokens.mjs — do not edit.
 * ${what}
 */
`;

const decl = (name, value, indent = '    ') => `${indent}${name}: ${value};`;

/** Aliases (deprecated names) whose target is `name` (without prefix). */
function aliasesOf(name) {
  const out = Object.entries(tokens.aliases).filter(([, target]) => target === name).map(([alias]) => `${PREFIX}${alias}`);
  out.push(...Object.entries(tokens.bareAliases).filter(([, target]) => target === name).map(([alias]) => alias));
  return out;
}

function semanticDeclarations(size, filter, indent) {
  const lines = [];
  for (const [name, spec] of Object.entries(tokens.semantic)) {
    if (!filter(spec)) continue;
    const value = resolveSemanticValue(spec[size]);
    lines.push(decl(`${PREFIX}${name}`, value, indent));
    for (const alias of aliasesOf(name)) lines.push(decl(alias, `var(${PREFIX}${name})`, indent));
  }
  return lines;
}

export function tokensCss() {
  const colors = readFileSync(join(here, 'colors.css'), 'utf8').trim();
  const base = baseTierVariables();
  const baseLines = [];
  for (const [name, value] of Object.entries(base)) {
    baseLines.push(decl(`${PREFIX}${name}`, value));
    for (const alias of aliasesOf(name)) baseLines.push(decl(alias, `var(${PREFIX}${name})`));
  }
  const darkLines = [
    ...Object.entries(tokens.elevation.dark).map(([name, value]) => decl(`${PREFIX}elevation-${name.slice(2)}`, value)),
    ...Object.entries(tokens.miscDark).map(([name, value]) => decl(`${PREFIX}${name}`, value)),
    ...Object.entries(tokens.color.dark).map(([name, value]) => decl(`${PREFIX}${name}`, value)),
  ];
  const viewport = (spec) => spec.scope === 'viewport';
  const container = (spec) => spec.scope !== 'viewport';
  const all = () => true;
  const compositeLines = Object.entries(tokens.composite).map(([name, value]) => decl(`${PREFIX}${name}`, value));
  const { sm, lg } = tokens.breakpoints;
  const ranges = containerRanges();
  const inner = (lines) => lines.map((line) => `  ${line}`).join('\n');

  return `${HEADER('Three tiers (D16): base scale, semantic tokens, and the semantic value per width.')}
${colors}

/* Tier 1 — base scale. Redeclared on .dark so a dark subtree resolves its own values. */
@layer base {
  :root, .dark {
${baseLines.join('\n')}
  }
  .dark {
${darkLines.join('\n')}
  }
}

/*
 * Tiers 2 + 3 — semantic tokens per width. Every token gets its viewport value on :root (the
 * outermost container; overlays are portaled there); container-scoped tokens are then set again
 * on the child of each \`.console-cq\` container from that container's width (D18), so a narrow
 * card on a wide screen still gets the narrow values. Children inherit them, so a component can
 * still override a token for its own subtree.
 */
@layer base {
  :root, .dark {
${semanticDeclarations('base', all, '    ').join('\n')}
${compositeLines.join('\n')}
  }
  @media (min-width: ${sm}) {
    :root, .dark {
${semanticDeclarations('sm', all, '      ').join('\n')}
    }
  }
  @media (min-width: ${lg}) {
    :root, .dark {
${semanticDeclarations('lg', all, '      ').join('\n')}
    }
  }

  .console-cq {
    container: console / inline-size;
  }
  @container console ${ranges.base} {
    :where(.console-cq) > :where(*) {
${inner(semanticDeclarations('base', container, '    '))}
    }
  }
  @container console ${ranges.sm} {
    :where(.console-cq) > :where(*) {
${inner(semanticDeclarations('sm', container, '    '))}
    }
  }
  @container console ${ranges.lg} {
    :where(.console-cq) > :where(*) {
${inner(semanticDeclarations('lg', container, '    '))}
    }
  }
}
`.replace(/\n{3,}/gu, '\n\n');
}

const THEME_COLORS = [
  'border', 'input', 'ring', 'background', 'foreground',
  ['primary', ['DEFAULT', 'foreground']],
  ['primary-action', ['DEFAULT', 'foreground', 'border']],
  ['secondary', ['DEFAULT', 'foreground']],
  ['destructive', ['DEFAULT', 'foreground']],
  ['muted', ['DEFAULT', 'foreground']],
  ['accent', ['DEFAULT', 'foreground']],
  ['success', ['DEFAULT', 'foreground']],
  ['warning', ['DEFAULT', 'foreground']],
  ['info', ['DEFAULT', 'foreground']],
  ['popover', ['DEFAULT', 'foreground']],
  ['card', ['DEFAULT', 'foreground']],
  ['selected', ['DEFAULT', 'foreground']],
  ['sidebar', ['DEFAULT', 'foreground', 'primary', 'primary-foreground', 'accent', 'accent-foreground', 'border', 'ring']],
];

/**
 * Color roles that do not follow the palette (tokens.color): `bg-brand`, `text-brand-foreground`,
 * `bg-signal-danger-fill`, `text-signal-warning-text`, `fill-chart-1`, …
 */
function roleColorLines() {
  return Object.keys(tokens.color.light).map((name) => decl(`--color-${name}`, `hsl(var(${PREFIX}${name}))`, '  '));
}

function colorLines() {
  const lines = [];
  for (const entry of THEME_COLORS) {
    if (typeof entry === 'string') {
      lines.push(decl(`--color-${entry}`, `hsl(var(--${entry}))`, '  '));
      continue;
    }
    const [name, shades] = entry;
    for (const shade of shades) {
      const variable = shade === 'DEFAULT' ? name : `${name}-${shade}`;
      lines.push(decl(`--color-${variable}`, `hsl(var(--${variable}))`, '  '));
    }
  }
  return lines;
}

export function themeCss() {
  const lines = [];
  const add = (name, value) => lines.push(decl(name, value, '  '));
  add('--spacing-0', '0rem');
  for (const [name, { tailwind }] of Object.entries(tokens.space)) add(`--spacing-${tailwind}`, `var(${PREFIX}${name})`);
  const sizes = sizingValues();
  for (const namespace of ['width', 'height', 'size', 'min-width', 'max-width', 'inset', 'translate', 'flex-basis']) {
    for (const [key, value] of Object.entries(sizes)) add(`--${namespace}-${key.replace('.', '\\.')}`, value);
  }
  for (const name of Object.keys(tokens.text)) {
    add(`--text-${name}`, `var(${PREFIX}text-${name})`);
    add(`--text-${name}--line-height`, `var(${PREFIX}leading-${name})`);
  }
  for (const name of Object.keys(tokens.weight)) add(`--font-weight-${name}`, `var(${PREFIX}weight-${name})`);
  for (const name of Object.keys(tokens.radius)) add(`--radius-${name.slice(2)}`, `var(${PREFIX}radius-${name.slice(2)})`);
  for (const [name, spec] of Object.entries(tokens.semantic)) {
    if (spec.kind === 'radius') add(`--radius-${name.replace(/-radius$/u, '')}`, `var(${PREFIX}${name})`);
  }
  for (const name of ['1', '2', '3']) add(`--shadow-e${name}`, `var(${PREFIX}elevation-${name})`);
  for (const [name, spec] of Object.entries(tokens.semantic)) {
    if (spec.kind === 'elevation') add(`--shadow-${name.replace(/-elevation$/u, '')}`, `var(${PREFIX}${name})`);
  }
  add('--font-sans', `var(${PREFIX}font-sans)`);
  add('--font-mono', `var(${PREFIX}font-mono)`);
  lines.push(...colorLines(), ...roleColorLines());
  // Every `transition-*` utility uses motion-fast and the one easing curve (zhinjs/console#125).
  add('--default-transition-duration', `var(${PREFIX}motion-fast)`);
  add('--default-transition-timing-function', `var(${PREFIX}ease-out)`);
  add('--animate-accordion-down', `accordion-down var(${PREFIX}motion-base) var(${PREFIX}ease-out)`);
  add('--animate-accordion-up', `accordion-up var(${PREFIX}motion-base) var(${PREFIX}ease-out)`);

  return `${HEADER('Tailwind 4 theme (D17): only on-scale keys. Import after `@import "tailwindcss"`.')}
/*
 * Defaults are cleared, then only the scale is offered:
 *   p-* / m-* / gap-* / space-*   0, px, 1, 2, 3, 4, 6, 8, 12, 16 (= space-1 … space-8)
 *   w / h / size / inset / min / max / translate / basis   Tailwind's numeric keys + control, control-compact, touch, badge
 *   text-*        ${Object.keys(tokens.text).join(', ')}
 *   font-*        ${Object.keys(tokens.weight).join(', ')}
 *   rounded-*     0–4, full + semantic (control, card, badge, popover, dialog, …)
 *   shadow-*      e1–e3 + semantic (card, card-hover, popover, dialog)
 *   breakpoints   ${Object.entries(tokens.breakpoints).map(([name, value]) => `${name} ${value}`).join(', ')}
 * Arbitrary values (p-[…]) are not blocked here; the ESLint rules of @zhin.js/console-ui/eslint are.
 */
@theme {
  --spacing: initial;
  --spacing-*: initial;
  --text-*: initial;
  --font-weight-*: initial;
  --radius-*: initial;
  --shadow-*: initial;
  --inset-shadow-*: initial;
  --drop-shadow-*: initial;
  --text-shadow-*: initial;
  --breakpoint-*: initial;
  --color-*: initial;
${Object.entries(tokens.breakpoints).map(([name, value]) => decl(`--breakpoint-${name}`, value, '  ')).join('\n')}
}

@theme inline {
${lines.join('\n')}

  @keyframes accordion-down {
    from { height: 0; }
    to { height: var(--radix-accordion-content-height); }
  }
  @keyframes accordion-up {
    from { height: var(--radix-accordion-content-height); }
    to { height: 0; }
  }
}

@custom-variant dark (&:where(.dark, .dark *));
`;
}

export function customMediaCss() {
  return `${HEADER('Breakpoints for the global shell (D16): `@media (--console-sm)`. Needs postcss-custom-media (or Lightning CSS drafts.customMedia).')}
${Object.entries(customMedia()).map(([name, query]) => `@custom-media ${name} ${query};`).join('\n')}
`;
}

export function scaleJson() {
  return `${JSON.stringify(buildScale(), null, 2)}\n`;
}

export const OUTPUTS = {
  'tokens.css': tokensCss,
  'theme.css': themeCss,
  'custom-media.css': customMediaCss,
  'scale.json': scaleJson,
};

export function generate({ check = false } = {}) {
  const stale = [];
  mkdirSync(GENERATED_DIR, { recursive: true });
  for (const [file, render] of Object.entries(OUTPUTS)) {
    const path = join(GENERATED_DIR, file);
    const content = render();
    let current = null;
    try { current = readFileSync(path, 'utf8'); } catch { /* missing */ }
    if (current === content) continue;
    if (check) stale.push(file);
    else writeFileSync(path, content);
  }
  return stale;
}

if (process.argv[1] === fileURLToPath(import.meta.url)) {
  const check = process.argv.includes('--check');
  const stale = generate({ check });
  if (stale.length) {
    console.error(`client/styles/generated is out of date (${stale.join(', ')}): run \`node tokens/generate.mjs\` in packages/console/ui.`);
    process.exit(1);
  }
}
